import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"27、【頤】 震下艮上","description":"橫渠易說 - 27、【頤】 震下艮上","frontmatter":{"title":"27、【頤】 震下艮上","description":"橫渠易說 - 27、【頤】 震下艮上"},"headers":[],"relativePath":"classics/hengqu/029.md","filePath":"classics/hengqu/029.md"}'),l={name:"classics/hengqu/029.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_27、【頤】-震下艮上" tabindex="-1">27、【頤】 震下艮上 <a class="header-anchor" href="#_27、【頤】-震下艮上" aria-label="Permalink to “27、【頤】 震下艮上”">​</a></h1><h3 id="彖曰-頤貞吉-養正則吉也。-觀頤-觀其所養也-自求口實-觀其自養也。天地養萬物-聖人養賢以及萬民-頤之時大矣哉" tabindex="-1">彖曰：“頤貞吉”，養正則吉也。“觀頤”，觀其所養也；“自求口實”，觀其自養也。天地養萬物，聖人養賢以及萬民，頤之時大矣哉! <a class="header-anchor" href="#彖曰-頤貞吉-養正則吉也。-觀頤-觀其所養也-自求口實-觀其自養也。天地養萬物-聖人養賢以及萬民-頤之時大矣哉" aria-label="Permalink to “彖曰：“頤貞吉”，養正則吉也。“觀頤”，觀其所養也；“自求口實”，觀其自養也。天地養萬物，聖人養賢以及萬民，頤之時大矣哉!”">​</a></h3><p>觀頤，辨養道得失，欲觀人處己之方。</p><h3 id="象曰-山下有雷-頤-君子以慎言語-節飲食。" tabindex="-1">象曰：山下有雷，頤，君子以慎言語，節飲食。 <a class="header-anchor" href="#象曰-山下有雷-頤-君子以慎言語-節飲食。" aria-label="Permalink to “象曰：山下有雷，頤，君子以慎言語，節飲食。”">​</a></h3><p>山下有雷，畜養之象。</p><h3 id="初九-舍爾靈龜-觀我朵頤-兇。-象曰-觀我朵頤-亦不足貴也。" tabindex="-1">初九，舍爾靈龜，觀我朵頤，兇。 象曰：“觀我朵頤”，亦不足貴也。 <a class="header-anchor" href="#初九-舍爾靈龜-觀我朵頤-兇。-象曰-觀我朵頤-亦不足貴也。" aria-label="Permalink to “初九，舍爾靈龜，觀我朵頤，兇。 象曰：“觀我朵頤”，亦不足貴也。”">​</a></h3><p>體躁應上，觀我而朵其頤，求養而無恥者也。</p><h3 id="六二-顛頤拂經-於丘頤-徵兇。-象曰-六二徵兇-行失類也。" tabindex="-1">六二，顛頤拂經，於丘頤，徵兇。 象曰：六二徵兇，行失類也。 <a class="header-anchor" href="#六二-顛頤拂經-於丘頤-徵兇。-象曰-六二徵兇-行失類也。" aria-label="Permalink to “六二，顛頤拂經，於丘頤，徵兇。 象曰：六二徵兇，行失類也。”">​</a></h3><p>凡頤之正，以貴養賤，以陽養陰，所謂經也。頤卦群陰皆當聽養於上，六二違之，反比於初，以陰養陽，顛頤者也。群陰，上所聚養者也，六二亂經於聚養之義，失陰類之常，故以進則兇。</p><h3 id="六三-拂頤-貞兇。十年勿用-無攸利。-象曰-十年勿用-道大悖也。" tabindex="-1">六三，拂頤，貞兇。十年勿用，無攸利。 象曰：“十年勿用”，道大悖也。 <a class="header-anchor" href="#六三-拂頤-貞兇。十年勿用-無攸利。-象曰-十年勿用-道大悖也。" aria-label="Permalink to “六三，拂頤，貞兇。十年勿用，無攸利。 象曰：“十年勿用”，道大悖也。”">​</a></h3><p>履邪好動，系說於上，不但拂經而已，害頤之正莫甚焉，故兇。“系說於上”一作“系而說上”。</p><h3 id="六四-顛頤-吉。虎視眈眈-其欲逐逐-無咎。-象曰-顛頤之吉-上施光也。" tabindex="-1">六四，顛頤，吉。虎視眈眈，其欲逐逐，無咎。 象曰：顛頤之吉，上施光也。 <a class="header-anchor" href="#六四-顛頤-吉。虎視眈眈-其欲逐逐-無咎。-象曰-顛頤之吉-上施光也。" aria-label="Permalink to “六四，顛頤，吉。虎視眈眈，其欲逐逐，無咎。 象曰：顛頤之吉，上施光也。”">​</a></h3><p>體順位陰，得頤之正，以貴養賤而得賢者，雖反陽爻養陰之義，以上養下，其施光矣。然以柔養剛，非嚴重其德，廣大其志，則未免於咎。</p><h3 id="六五-拂經-居貞吉。不可涉大川。-象曰-居貞之吉-順以從上也。" tabindex="-1">六五，拂經，居貞吉。不可涉大川。 象曰：居貞之吉，順以從上也。 <a class="header-anchor" href="#六五-拂經-居貞吉。不可涉大川。-象曰-居貞之吉-順以從上也。" aria-label="Permalink to “六五，拂經，居貞吉。不可涉大川。 象曰：居貞之吉，順以從上也。”">​</a></h3><p>聽養於上，正也；以陰居頤卦之尊，拂經也。</p><h3 id="上九-由頤-厲吉-利涉大川。-象曰-由頤厲吉-大有慶也。" tabindex="-1">上九，由頤，厲吉，利涉大川。 象曰：“由頤厲吉”，大有慶也。 <a class="header-anchor" href="#上九-由頤-厲吉-利涉大川。-象曰-由頤厲吉-大有慶也。" aria-label="Permalink to “上九，由頤，厲吉，利涉大川。 象曰：“由頤厲吉”，大有慶也。”">​</a></h3><p>由頤自危然後乃吉者，下有眾陰順從之慶，驕則有它吝。此卦得養之正者方利涉大川，蓋養然後可動耳。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
